        {
          "key": "averyClaypool",
          "title": "",
          "body": "更多成员陆续到达。第一位是一名30多岁的男子，留着一小撮金色胡须，有着明亮的绿色眼睛。“艾弗里·克莱普尔先生。”肯斯勒博士把你介绍给那名男子，你们握了握手。“克莱普尔先生是埃尔斯沃思先生的……熟人。他将担任我们的南极向导。\n\n“只要老天爷愿意行个方便。”克莱普尔开玩笑道，“说实话，我们哪怕能从冰架上下来，就已经很幸运了。”\n\n“我坚信在有了你的技术，我们至少能走得和戴尔和莱克他们一样远。”\n\n“这正是我担心的。”克莱普尔嘟囔着，快步地走过肯斯勒，上了跳板。他往上走，经过了埃尔斯沃思，然后两人四目相对，仿佛被定住了一般。你发誓，当他们一句话都不说僵持着时，温度下降了好几度。\n\n“他们的关系一直是……比较好的。”肯斯勒博士小声说，“但最近却出现了一些问题。他们最好学会容忍彼此的差异。毕竟，他们会在很长一段时间里避不开对方了。”你看到克莱普尔的目光在埃尔斯沃思身上徘徊了片刻，然后他愤怒地转身进入船舱。\n\n接下来抵达的是一位有着浅棕色皮肤和疲倦眼睛的女子，除了她的行李，还有一个挂着白色十字的巨大亮红的医疗箱摆在一起。她伸出手与肯斯勒博士握了握，而你留意到她的手在紧张地颤抖。“感谢你参加我们的这次航行， 玛拉。”\n\n“噢，艾米。总得有人负责你的生命安全。”她回答道。肯斯勒博士抬眼将那名女子从头到脚打量一遍，有那么一刻出现了尴尬的沉默，她的脸颊微微发红。“嗯。那就这样。”她说了句，然后继续往船上走。",
          "text": "更多成员陆续到达。第一位是一名30多岁的男子，留着一小撮金色胡须，有着明亮的绿色眼睛。“艾弗里·克莱普尔先生。”肯斯勒博士把你介绍给那名男子，你们握了握手。“克莱普尔先生是埃尔斯沃思先生的……熟人。他将担任我们的南极向导。\n\n“只要老天爷愿意行个方便。”克莱普尔开玩笑道，“说实话，我们哪怕能从冰架上下来，就已经很幸运了。”\n\n“我坚信在有了你的技术，我们至少能走得和戴尔和莱克他们一样远。”\n\n“这正是我担心的。”克莱普尔嘟囔着，快步地走过肯斯勒，上了跳板。他往上走，经过了埃尔斯沃思，然后两人四目相对，仿佛被定住了一般。你发誓，当他们一句话都不说僵持着时，温度下降了好几度。\n\n“他们的关系一直是……比较好的。”肯斯勒博士小声说，“但最近却出现了一些问题。他们最好学会容忍彼此的差异。毕竟，他们会在很长一段时间里避不开对方了。”你看到克莱普尔的目光在埃尔斯沃思身上徘徊了片刻，然后他愤怒地转身进入船舱。\n\n接下来抵达的是一位有着浅棕色皮肤和疲倦眼睛的女子，除了她的行李，还有一个挂着白色十字的巨大亮红的医疗箱摆在一起。她伸出手与肯斯勒博士握了握，而你留意到她的手在紧张地颤抖。“感谢你参加我们的这次航行， 玛拉。”\n\n“噢，艾米。总得有人负责你的生命安全。”她回答道。肯斯勒博士抬眼将那名女子从头到脚打量一遍，有那么一刻出现了尴尬的沉默，她的脸颊微微发红。“嗯。那就这样。”她说了句，然后继续往船上走。",
          "status": "present-needs-review"
        },
        {
          "key": "malaSinha",
          "title": "",
          "body": "等她走远了，肯斯勒博士清了清喉咙。“玛拉·辛哈医生，是我们的医师。”她解释道，“说服她加入我们花了不少时间，所以尽量不要在一些无关紧要的问题上滥用她的专业技能。冻伤会是很严重的问题，还有坏疽和体温过低也是。请尽量不要惹她生气。”你不确定肯斯勒博士是否在开玩笑。\n\n男子的声音伴随着一阵犬吠打破了这突然的寂静。“安雨！该死的，安雨，别这样乱跑！”他大吼。",
          "text": "等她走远了，肯斯勒博士清了清喉咙。“玛拉·辛哈医生，是我们的医师。”她解释道，“说服她加入我们花了不少时间，所以尽量不要在一些无关紧要的问题上滥用她的专业技能。冻伤会是很严重的问题，还有坏疽和体温过低也是。请尽量不要惹她生气。”你不确定肯斯勒博士是否在开玩笑。\n\n男子的声音伴随着一阵犬吠打破了这突然的寂静。“安雨！该死的，安雨，别这样乱跑！”他大吼。",
          "status": "present-needs-review"
        },
        {
          "key": "eliyahAshevak",
          "title": "",
          "body": "“那是阿什瓦克先生。”肯斯勒博士说道，从她的名单上划去另一个名字。过了一会，你看到一只灰毛大狗向你扑来，兴奋地伸出舌头。你俯下身抚摸它，用手滑过它又厚又长的毛发。后面的男子终于追了上来，上气不接下气。“安雨……拜托，我以为我……已经把你训练好了。”他边喘边说。\n\n“伊里亚·阿什瓦克是我们的驯犬师。”肯斯勒博士打断了他，“他负责照顾我们带来的44只雪橇犬，当然还有喂养和训练它们。”\n\n“算上安雨是45只。”他纠正了她，然后转身与你握手。“还有，我们会在这艘船上共处一段时间，所以我们还是不要那么拘谨了。叫我‘伊里亚’就好。”",
          "text": "“那是阿什瓦克先生。”肯斯勒博士说道，从她的名单上划去另一个名字。过了一会，你看到一只灰毛大狗向你扑来，兴奋地伸出舌头。你俯下身抚摸它，用手滑过它又厚又长的毛发。后面的男子终于追了上来，上气不接下气。“安雨……拜托，我以为我……已经把你训练好了。”他边喘边说。\n\n“伊里亚·阿什瓦克是我们的驯犬师。”肯斯勒博士打断了他，“他负责照顾我们带来的44只雪橇犬，当然还有喂养和训练它们。”\n\n“算上安雨是45只。”他纠正了她，然后转身与你握手。“还有，我们会在这艘船上共处一段时间，所以我们还是不要那么拘谨了。叫我‘伊里亚’就好。”",
          "status": "present-needs-review"
        },
        {
          "key": "williamDyer",
          "title": "",
          "body": "当这名男子和他的大狗登上船时，你询问肯斯勒博士是否收到了你寄出的信，是关于戴尔教授担忧的事情的。“我很清楚他的报告。”肯斯勒博士回答道，“但正如我一再告诉他的，我并不打算停止或推迟这次探险——”就在这时，脚步声从你身后传来，打断了你们的谈话。\n\n“——说曹操，曹操到。”肯斯勒博士喃喃自语着，将视线从写字板上移开，抬起头来。来的不是别人，正是威廉·戴尔教授和他的学生丹佛斯，他俩都提着几包行李。“我很高兴你最终决定加入我们，威廉。”\n\n“艾米。”他应声回答，“我来这里不是因为我相信你们的宗旨。我是来确保你和你的同伴不会自己送死。你根本不知道你将要面对的是什么。”\n\n“那你在路上不就有的是机会好好教育我们了。”她转过身来对年轻的丹佛斯说话，而此时丹佛斯正抬头盯着油轮，表情痛苦。“丹佛斯，我希望你明白，你没有义务参加这次探险。在你经历了那么多之后……”她声音越来越小，担心地扬起眉毛，这与她平时冷淡的举止对比鲜明。\n\n“感谢您的关心，肯斯勒博士，但我期待着有机会返回南极。我想要……需要……再去那儿。”\n\n她跟随他的目光注视着菲奥多西亚号，它在波涛汹涌的大西洋海面上稳定地上下沉浮。“那好吧。我们还在把所有设备装上船。埃尔斯沃思先生会带你们前往所属的房间。”你点点头，开始和剩下的船员以及其余的探险队成员——大部分是大学的学生，还有几位独立的探险者，以及几位不同领域的研究人员——一起登船。你再一次看向空中那一缕阳光，直到它被灰云完全吞噬。",
          "text": "当这名男子和他的大狗登上船时，你询问肯斯勒博士是否收到了你寄出的信，是关于戴尔教授担忧的事情的。“我很清楚他的报告。”肯斯勒博士回答道，“但正如我一再告诉他的，我并不打算停止或推迟这次探险——”就在这时，脚步声从你身后传来，打断了你们的谈话。\n\n“——说曹操，曹操到。”肯斯勒博士喃喃自语着，将视线从写字板上移开，抬起头来。来的不是别人，正是威廉·戴尔教授和他的学生丹佛斯，他俩都提着几包行李。“我很高兴你最终决定加入我们，威廉。”\n\n“艾米。”他应声回答，“我来这里不是因为我相信你们的宗旨。我是来确保你和你的同伴不会自己送死。你根本不知道你将要面对的是什么。”\n\n“那你在路上不就有的是机会好好教育我们了。”她转过身来对年轻的丹佛斯说话，而此时丹佛斯正抬头盯着油轮，表情痛苦。“丹佛斯，我希望你明白，你没有义务参加这次探险。在你经历了那么多之后……”她声音越来越小，担心地扬起眉毛，这与她平时冷淡的举止对比鲜明。\n\n“感谢您的关心，肯斯勒博士，但我期待着有机会返回南极。我想要……需要……再去那儿。”\n\n她跟随他的目光注视着菲奥多西亚号，它在波涛汹涌的大西洋海面上稳定地上下沉浮。“那好吧。我们还在把所有设备装上船。埃尔斯沃思先生会带你们前往所属的房间。”你点点头，开始和剩下的船员以及其余的探险队成员——大部分是大学的学生，还有几位独立的探险者，以及几位不同领域的研究人员——一起登船。你再一次看向空中那一缕阳光，直到它被灰云完全吞噬。",
          "status": "present-needs-review"
        }
