            "key": "checkpoint1.theDisappearance1",
            "title": "检查点I：失踪事件",
            "body": "失踪事件 1：你睡的一点也不舒服。令人发疯的寒冷噬咬着你的身体，不停呼啸的狂风让你胡思乱想着，或许会有怪异的墨状怪形从地下冒出来，把所有人撕成碎片。\n\n正当你终于开始摆脱这些可怕的想法时，一声惊叫打断了你的休息。你醒来时发现营地一片混乱，有几个同伴失踪了。令你沮丧的是，足迹离开了相对安全的营地，延伸到了冰冻荒野之中。\n\n找到并收齐探险队中存活成员的剧情支援。混洗他们并从中随机选择等于你营地庇护值数量的支援。这些角色是安全的。\n\n如果探险队的所有存活成员都是安全的，推进至 失踪事件 2。\n\n剩余的探险队成员在夜晚失踪了。在剧本日志中“探险队”部分，在每名失踪角色的名字旁写下“失踪”。\n\n调查员必须选择一项：• 他们只能靠自己了。 你将跳过冒险的下一部分。推进至 失踪事件 2。\n\n• 去寻找失踪队员。你将进行本冒险的下一部分。跳过并推进至 失踪事件 3。",
