            "key": "checkpoint3.theOtherSide1",
            "title": "检查点III：彼端",
            "body": "彼端 1：你在大门彼端的薄雾中醒来。你不知道你到大门这边已经过了多久了。\n\n如果你希望继续进行，进入 彼端 2，或者进入 彼端 3 休息一下再继续。",
            "text": "检查点III：彼端\n\n彼端 1：你在大门彼端的薄雾中醒来。你不知道你到大门这边已经过了多久了。\n\n如果你希望继续进行，进入 彼端 2，或者进入 彼端 3 休息一下再继续。",
            "status": "present-needs-review"
