            "key": "interlude3.cookieIsAlive",
            "title": "",
            "body": "如果詹姆斯·“曲奇”·弗雷德里克斯活着：\n\n你走近时，曲奇拔出了他的柯尔特手枪。你可以从他充血的眼睛和颤抖的手看出，他有一段时间没有休息过了。当他意识到是你时，他道歉并放下了武器。“我还以为是——嗯，你懂的。”他敷衍地解释着。你说他还能管的住扣扳机的手，自己真是走运。“呵，管的住手。”他语气讥讽地回应。然后是一段时间的沉默。“好了。来帮我生下火。”在沉默中，你和头发花白的老兵把剩下的柴火放在营地中心，试图点燃它。在寒冷潮湿的环境下，你们花了将近半小时的努力才生起了火。它急切地消耗着燃料，在洞穴冰冷的墙壁上投下跳动的影子。最终，曲奇打破了沉默。“这个。”他决然地说道。“我记得这个。”你不必费心去问——只要看看他那凝望远处的目光，你就知道他指的是弥漫在营地里，即将到来的死亡的感觉。“给你个忠告。他说，“到时候，你绝不能犹豫。”不管我们还剩下多少人。不管你面对的是怎样的灾厄。一旦退缩，你就会死。”你点头表示理解。你感觉曲奇这辈子从没退缩过一次。\n\n曲奇的建议帮助你为接下来的旅程做好准备。任意一位调查员获得1点奖励经验值。",
