            "body": "如果艾弗里·克莱普尔活着：\n\n你走近时，克莱普尔正端详着冰冷的墙壁，眉头因忧虑而紧锁。“这里本该更暖和才对，”他指出，“可就算不计风寒效应，这里也要冷上将近10度。”就在这时，冰层里有东西动了一下——也许是一道影子，也许是冰面反射出的什么。那道转瞬即逝的暗影旋转着消失了，你和克莱普尔本能地后退。你身后的任何光线都不可能投出那样的影子。“这块冰……有点不对劲。”克莱普尔低声说。“这种寒冷是不自然的。戴尔的报告将这些内部建筑描述为温暖宜居，可这里却……”你们交换了一个心照不宣的眼神。“我们必须做好准备。应对任何情况。”\n\n克莱普尔的预测帮助你远离恶劣天气。从混乱袋里移除1个[frost]标记。",
