            "key": "interlude3.ellsworthIsAlive",
            "title": "",
            "body": "如果罗尔德·埃尔斯沃思活着：\n\n你已经知道埃尔斯沃思走近你的时候在想什么了，他一手拿着提灯，一手拿着冰锥。“跟我一起走一段？”他把提灯递给你，然后你们一起离开营地。你们在探索冰冷深渊的路上谨慎地低声交谈。你们两个人走到了和队伍里的其他人都到不了的遥远地方。“你一定认为我疯了，要不就是傻了。”经过一小时快节奏的跋涉后，他说道，总是独自前行，陷入这样的危险。进入我们不该去的地方。”你耸耸肩，指出了事实：你也和他在一起。“没错。所以我怀疑你对我的看法是否公正。”他开玩笑说。\n\n一股阴冷、恶臭的空气从洞穴里吹出来，就像一只巨兽呼出的气，要把你吞入它的喉咙。“嗯，不管怎样，我很高兴有你在这里。”这位探险家承认道，他的声音有些犹豫。“看——”他指着前方隧道的岔路口。那股恶臭的风在你周围渐渐消失了，但它显然是来自左边的路。“那边有什么在做空气回圈。这肯定意味着什么，对吧？”你点头表示赞同，但你肯定不喜欢这该死的味道……\n\n和埃尔斯沃思一起侦察使你洞悉之后的旅程。在剧本日志中，记录下调查员侦察了分岔通道。",
