          "body": "检查剧本日志。 只有当调查员在战役中胜利，且所对应的探险队队员生还的情况下，按照顺序阅读以下条目",
          "text": "尾声\n\n检查剧本日志。 只有当调查员在战役中胜利，且所对应的探险队队员生还的情况下，按照顺序阅读以下条目",
