        "specialRules": {
          "0": {
            "title": "幻景",
            "body": "幻景关键词代表那些由你的记忆与同伴们的记忆所化的地点。这些地点没有未揭示面，因此入场时以已揭示面朝上。这些地点的背面不是未揭示面，而是剧情卡牌。这些剧情卡牌让调查员能够深入这片奇异的幻景，并以地点或遭遇卡牌的形式解锁新的记忆。幻景关键词所标示的数字代表将其翻面所需的线索数量，而括号中的卡牌名则表明因此可能出现的记忆。\n\n• 作为一项[action]能力，位于幻景地点的调查员可以作为一个团队花费所标示数量的线索，将其翻面并结算其另一面的剧情卡。\n\n• 当一个带有幻景关键词的地点入场时（包括在设置期间），对于其幻景关键词所指、且已经位于场上或胜利区的每张卡牌，将该地点的线索值减少其幻景值。\n\n• 注：在你第一次游玩《致命幻景》时，这种情况不太会发生，但在之后的多次游玩中则很有可能发生。\n\n• 例如：记忆囚笼的线索值为3[per_investigator]，且具有以下文本：“幻景1[per_investigator]（大本营、菲奥多西亚号甲板、大学礼堂）。”当记忆囚笼入场时，调查员检查其幻景关键词所指的三张卡牌中，哪些已经位于场上或胜利区。大学礼堂与菲奥多西亚号甲板都已经在场上，但大本营仍被放在一边。因此，记忆囚笼的线索值减少2[per_investigator]，这意味着它入场时其上只放置1[per_investigator]个线索。\n\n• 如果一个地点由其幻景关键词所指的每张卡牌都已经位于场上或胜利区，则该地点“已破除幻景”。已破除幻景的地点不能再次翻面。"
          }
        },
