      "chineseGaps": {},
      "intro": "冒险：致命幻景\n\n如果这是你第一次进入致命幻景，进入 序言 1。 否则，则进入 序言 2。\n\n序言 1：一进入门口，你就发现自己在一个冰冷的隧道网络中，里面充斥着瘴气，还滴着五光十色的脓水。你的倒影在无数奇特的角度注视着你。你的声音在这无尽的镜子大厅里回响。你转身，却发现入口已经消失在你身后。然后，在你的眼角，你发现一个熟悉的身影穿过同样的迷雾——但是，不，那不可能。那可能吗？\n\n找到并阅读下方与在坠机事故中遇难角色对应的章节。 然后进入 设置。\n\n冒险：致命幻景\n\n如果这是你第一次进入致命幻景，进入 序言 1。 否则，则进入 序言 2。\n\n又一次，你发现自己置身于一个冰冷的隧道网络中，弥漫着雾气和瘴气。入口在你身后消失了。你的倒影，闪烁着虚幻微弱的暗示，从众多角度同时盯着你。\n\n进入 设置。",
      "setup": "将下列遭遇组中的所有卡牌找出：致命幻景、未知使徒、惨遭抛弃、危险瘴气、无名恐怖、沉默与神秘、忒咳哩-哩以及寒冷刺骨。这些遭遇组由下列图标表示：\n\n仅使用密谋1构建密谋牌堆。将剩余的密谋移出游戏。\n\n仅使用幕1构建幕牌堆。将剩余的幕移出游戏。\n\n将记忆囚笼地点放置入场，已揭示面朝上。\n\n每位调查员从记忆囚笼开始游戏。\n\n将其他每个地点放在一边，位于场外。\n\n将下列每张卡牌放在一边，位于场外：九张“……之记忆”敌人，以及九张坚毅剧情支援。\n\n如果这是你第二次游玩《致命幻景》，则仅使用密谋2构建密谋牌堆；如果这是第三次，则仅使用密谋3。将剩余的密谋移出游戏。\n\n如果这是你第二次游玩《致命幻景》，则仅使用幕2构建幕牌堆；如果这是第三次，则仅使用幕3。将剩余的幕移出游戏。\n\n找出剧本日志中列在“驱除的记忆”下的每张剧情卡牌。将这些卡牌放入胜利区。\n\n将其余每张“……之记忆”敌人放在一边，位于场外。\n\n找出剧本日志中列在“发现的记忆”下的每个地点。将这些地点连同记忆囚笼一起放置入场，已揭示面朝上（记得根据幻景关键词调整每个地点的线索值）。\n\n每位调查员从记忆囚笼开始游戏。\n\n将其他每个地点放在一边，位于场外。\n\n将九张坚毅剧情支援中尚未在之前游玩《致命幻景》时获得的那些放在一边。\n\n检查难度等级。\n\n如果你游玩的是困难难度，则在密谋上放置1个毁灭标记。\n\n如果你游玩的是专家难度，则在密谋上放置2个毁灭标记。\n\n将所有尚未加入调查员牌库的忒咳哩-哩弱点卡牌混洗到一起，形成忒咳哩-哩牌堆。将该牌堆放在密谋牌堆旁。",
      "resolutions": {},
