        "intro2": {
          "title": "疯狂之心 第II部分",
          "body": "序言 2：肯斯勒博士一边研究古代壁画，一边解释了一切。“这些古老者是旅者。殖民者。它们在十多亿年前就来到了地球。”她引用戴尔教授的笔记说，“但它们不是最早到达这儿的。这个地方，所有这一切——在那时都是远古的存在。”她一边用手摸着壁画，一边解释她了解到的东西。“但这个存在并非被困于此。”\n\n你问她这是什么意思，你被这种新的理解吓到了。她转过身来面对着你，眼睛闪耀着智慧的光芒。“我一直在研究它们的生理，试图辨别它们是如何以它们现在的方式存在的，没有形状、没有物质、没有状态。但我的想法全错了。无机物哪来的生物学呢。看，它都不是个生物，不是真实的。它更像是……”她犹豫了一下，试图找到合适的词语，“它是另一个维度。另一种现实，叠加在我们的现实上。所有这一切都是一个有意识的微观宇宙。它不是由有机生命组成的，只是在模仿有机体而已。\n\n对你所遇到的幽灵和你所看到的幻景的全新解释，使一切都说得通了。它们不是被你杀死的怪物，它们只是虚假现实中的虚假之物。而这虚假却将可能成为现实。你询问肯斯勒博士，是否还有希望阻止这股力量逃跑。\n\n“它不是活物。它不能被杀死。只能被控制。古老者的设施里有五个高塔，在利用它的精华为它们的文明提供动力，但过了这么久，恐怕它们已无法工作了。但也许……”她说到这里，开始制定一个计划。终于，她睁大眼睛表示想通了。“我知道必须要做什么了。我知道该怎么阻止它。你必须找到这些塔并摧毁它们——这样做会摧毁这整个区域。与此同时……”她把背包从肩上卸下，扔到了地上。“我……我现在必须得走了。没有时间可以浪费了。”\n\n你反对她的突然离开，但她已经下定了决心。她后退了几步，踌躇地看了同伴最后一眼，然后飞快地跑开了。看在你们所有人的份上……你希望她知道自己在做什么。\n\n在剧本日志中记录，肯斯勒博士有一个计划。 本场游戏艾米·肯斯勒博士不能被调查员选择为陪同者。\n\n进行 设置。"
        },
        "intro3": {
          "title": "疯狂之心 第II部分",
          "body": "在这些古代壁画中，你只能收集到隐于其中的一小部分真相，但你的发现已经几乎令人难以置信了。当古老者在十多亿年前来到地球时，它们不仅殖民了南极，还殖民了整个地球。而当它们做着这些的时候，这里——以及住在里面的存在——其实早就在了。它们在它周围建造了建筑群，以研究内部的远古存在，从而更好地了解它。而在这过程中，吸引了甚至超出它们所知的力量。大门和封印是用来控制它的，但年久失修使它变得衰弱失效。你怀疑是因为南极洲上智慧生命的出现——开始探索其长期沉寂的山峰和冰原的人类——唤醒了潜藏于此的存在。\n\n壁画说明了这个设施的结构，五座塔的建造不仅是为了控制那生物的本质，还为整个古老者文明提供动力。你只能想到，摧毁这些塔将会使整个区域——甚至可能使它所在的整座山——变成废墟。你不知道你是否能真正摧毁或遏制这无名的恐怖，但你别无选择，只能尝试。如果它继续逃离，现实的概念本身将被它随心所欲地改写。现实中除了幻景，其他什么都不会有了。除了扭曲可怕的想象，什么都不会有了。只有永远无法醒来的噩梦。\n\n在剧本日志中记录， 你尚未明了幻景的真相。\n\n进行设置。"
        },
